import{_ as l,o as i,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS G/H (Day 2) - Calamari Localization","description":"","frontmatter":{"title":"CDS G/H (Day 2) - Calamari Localization","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["Ceph","Calamari","Localization","Gettext","User Interface"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.md","filePath":"posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.md","lastUpdated":1780459816000}'),r={name:"posts/2014/CDS_G_H_Day_2_-_Calamari_Localization.md"};function o(n,a,s,_,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>[会议时间]</p><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>Calamari 本地化讨论</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Jen（Calamari 本地化项目负责人）</li><li>Xi&#39;an（Calamari 本地化讨论主持人）</li><li>Lee（可能稍后加入）</li><li>其他相关人员</li></ul><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. Calamari 本地化项目介绍</strong></p><ul><li>Jen 介绍了 Calamari 本地化项目的背景和目标，旨在将 Calamari 的界面和功能翻译成中文，以提高用户体验。</li><li>目前 Calamari 提供了监控视图、OSD 管理、信息等功能，但界面内容尚未本地化。</li></ul><p><strong>2. 本地化方法讨论</strong></p><ul><li>讨论了使用 Gettext 工具进行本地化的方法，该工具可以将要翻译的消息封装在函数中，然后通过模板进行翻译。</li><li>强调了本地化过程中需要注意的问题，例如确保内容易于复制和推广，以及选择哪些内容需要翻译。</li></ul><p><strong>3. 本地化资源文件</strong></p><ul><li>讨论了创建本地化资源文件，如 po 文件，用于存储翻译后的内容。</li><li>确定首先从界面元素开始翻译，例如用户名、密码、登录按钮等。</li></ul><p><strong>4. 本地化工具和协作</strong></p><ul><li>讨论了使用 Google Drive 或 Google Docs 进行协作，共享截图和标注。</li><li>由 Jen 和 Gregory 负责整理和标注界面截图。</li></ul><p><strong>5. Calamari 功能讨论</strong></p><ul><li>讨论了 Calamari 的功能需求，例如支持更多 OSD 节点，提供更多 OSDD 统计信息和更详细的错误报告。</li></ul><p><strong>6. 行动计划</strong></p><ul><li>Jen 和 Gregory 负责整理界面截图并进行标注。</li><li>社区成员参与翻译工作。</li><li>Gregory 将参与本地化项目，提供技术支持。</li></ul><h4 id="关键词" tabindex="-1">关键词： <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词：&quot;">​</a></h4><ul><li>Calamari</li><li>本地化</li><li>Gettext</li><li>翻译</li><li>界面</li><li>OSD</li><li>统计信息</li><li>错误报告</li><li>UI</li></ul><h3 id="改进点" tabindex="-1">改进点 <a class="header-anchor" href="#改进点" aria-label="Permalink to &quot;改进点&quot;">​</a></h3><ul><li>保留了所有 Ceph 相关的关键词。</li><li>确保了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划都被准确反映。</li><li>修正了一些可能的误解，如将“calamari”和“get text”等关键词保留在总结中。</li><li>补充了会议中提到的功能需求和技术细节。</li></ul>',25)])])}const p=l(r,[["render",o]]);export{c as __pageData,p as default};
